package render

import (
	"fmt"
	"nqueen-zoo/pkg/board"
	"strings"
)

// Renderer handles the visual output of the N-Queens board.
type Renderer struct {
	UseColor bool
}

// NewRenderer creates a new renderer instance.
func NewRenderer(useColor bool) *Renderer {
	return &Renderer{UseColor: useColor}
}

const (
	Reset       = "\033[0m"
	Bold        = "\033[1m"
	Red         = "\033[38;5;196m"
	Green       = "\033[38;5;46m"
	Yellow      = "\033[38;5;226m"
	Blue        = "\033[38;5;21m"
	Gray        = "\033[38;5;240m"
	BrightWhite = "\033[97m"
)

// RenderBoard prints the board to the terminal with Unicode characters and optional heatmaps.
func (r *Renderer) RenderBoard(b *board.Board, showHeatmap bool) {
	size := b.Size
	if size == 0 {
		fmt.Println("Empty board.")
		return
	}

	heatmap := [][]int{}
	if showHeatmap {
		heatmap = b.GetAttackHeatmap()
	}

	fmt.Println(strings.Repeat("-", size*3))
	for row := 0; row < size; row++ {
		var line strings.Builder
		line.WriteString(fmt.Sprintf("%2d | ", row))
		for col := 0; col < size; col++ {
			// Determine symbol and color based on state
			symbol := "·"
			color := ""

			isQueen := false
			for _, q := range b.Queens {
				if q.Row == row && q.Col == col {
					isQueen = true
					break
				}
			}

			if isQueen {
				symbol = "♛"
				color = Bold + BrightWhite
			} else if showHeatmap {
				count := heatmap[row][col]
				if count > 1 {
					color = Red        // Heavy attack
				} else if count == 1 {
					color = Gray       // Light attack/influence
				}
			}

			line.WriteString(fmt.Sprintf("%s%s%s ", color, symbol, Reset))
		}
		fmt.Println(line.String())
	}
	fmt.Println(strings.Repeat("-", size*3))
	fmt.Println("   " + strings.Repeat("───", size))
}

// RenderNarrative prints the educational commentary in a distinct style.
func (r *Renderer) RenderNarrative(text string) {
	fmt.Printf("\n%s[Narrator]: %s%s\n\n", Bold, text, Reset)
}

package main

import (
	"bufio"
	"flag"
	"fmt"
	"os"
	"runtime"
	"strings"
	"time"

	"nqueen-zoo/pkg/board"
	"nqueen-zoo/pkg/render"
	"nqueen-zoo/pkg/solver"
)

func main() {
	mode := flag.String("mode", "tutorial", "Mode to run: tutorial, benchmark, or play")
	n := flag.Int("n", 8, "Size of the board (N)")
	useColor := flag.Bool("color", true, "Enable ANSI colors")
	flag.Parse()

	r := render.NewRenderer(*useColor)

	switch *mode {
	case "benchmark":
		runBenchmark(*n)
	case "play":
		runInteractivePlay(*n, r)
	case "tutorial":
		fallthrough
	default:
		runTutorial(*n, r)
	}
}

func runBenchmark(n int) {
	fmt.Printf("=== N-Queens Benchmark (N=%d) ===\n", n)

	// Backtracking for small N
	if n <= 14 {
		fmt.Print("Running Bitwise Backtracking Solver... ")
		start := time.Now()
		var m1 runtime.MemStats
		runtime.ReadMemStats(&m1)

		btSolver := &solver.BacktrackingSolver{}
		_, err := btSolver.Solve(n)

		var m2 runtime.MemStats
		runtime.ReadMemStats(&m2)
		elapsed := time.Since(start)

		if err != nil {
			fmt.Printf("Failed: %v\n", err)
		} else {
			fmt.Printf("Done!\nTime: %v\nAllocated: %v KB\n\n", elapsed, (m2.TotalAlloc-m1.TotalAlloc)/1024)
		}
	} else {
		fmt.Println("Skipping Backtracking (N is too large, it would take too long).")
	}

	// Min-Conflicts for larger N
	fmt.Print("Running Min-Conflicts Heuristic Solver... ")
	start := time.Now()
	var m1 runtime.MemStats
	runtime.ReadMemStats(&m1)

	mcSolver := &solver.MinConflictsSolver{}
	_, err := mcSolver.Solve(n)

	var m2 runtime.MemStats
	runtime.ReadMemStats(&m2)
	elapsed := time.Since(start)

	if err != nil {
		fmt.Printf("Failed: %v\n", err)
	} else {
		fmt.Printf("Done!\nTime: %v\nAllocated: %v KB\n\n", elapsed, (m2.TotalAlloc-m1.TotalAlloc)/1024)
	}
}

func runTutorial(n int, r *render.Renderer) {
	fmt.Println("👑 Welcome to the N-Queens Educational Visualizer! 👑")
	fmt.Println("We will explore how a Backtracking Algorithm solves this puzzle step-by-step.")
	fmt.Println("Press [ENTER] to advance each step, or type 'q' and press [ENTER] to quit.")
	fmt.Println()

	btSolver := &solver.BacktrackingSolver{}
	steps := btSolver.GetSteps(n)

	scanner := bufio.NewScanner(os.Stdin)
	stepCount := 0

	for step := range steps {
		stepCount++
		r.RenderNarrative(step.Narrative)
		r.RenderBoard(step.Board, true)

		fmt.Printf("Step %d | Press [ENTER] to continue (or 'q' to quit): ", stepCount)
		if scanner.Scan() {
			text := strings.TrimSpace(scanner.Text())
			if strings.ToLower(text) == "q" {
				fmt.Println("Exiting tutorial. Have a great day!")
				return
			}
		}
	}
}

func runInteractivePlay(n int, r *render.Renderer) {
	fmt.Println("🎮 Welcome to Manual Play Mode! 🎮")
	fmt.Println("Try placing queens one by one without getting attacked.")
	b := board.NewBoard(n)
	scanner := bufio.NewScanner(os.Stdin)

	for len(b.Queens) < n {
		r.RenderBoard(b, true)
		fmt.Printf("Enter Row and Column to place Queen #%d (e.g. '0 3') or 'q' to quit: ", len(b.Queens)+1)

		if !scanner.Scan() {
			break
		}
		text := strings.TrimSpace(scanner.Text())
		if strings.ToLower(text) == "q" {
			return
		}

		var row, col int
		_, err := fmt.Sscanf(text, "%d %d", &row, &col)
		if err != nil || row < 0 || row >= n || col < 0 || col >= n {
			fmt.Println("❌ Invalid input. Please enter two numbers separated by a space.")
			continue
		}

		pos := board.Position{Row: row, Col: col}
		if !b.AddQueen(pos) {
			fmt.Println("⚠️ That square is under attack or invalid! Try a different one.")
		} else {
			fmt.Println("✅ Queen placed successfully!")
		}
	}

	r.RenderBoard(b, false)
	fmt.Println("🎉 Congratulations! You successfully placed all Queens safely!")
}

package board_test

import (
	"testing"
	"nqueen-zoo/pkg/board"
)

func TestNewBoard(t *testing.T) {
	b := board.NewBoard(4)
	if b.Size != 4 {
		t.Errorf("Expected board size 4, got %d", b.Size)
	}
	if len(b.Queens) != 0 {
		t.Errorf("Expected 0 queens initially, got %d", len(b.Queens))
	}
}

func TestIsSafe(t *testing.T) {
	tests := []struct {
		name     string
		size     int
		queens   []board.Position
		testPos  board.Position
		expected bool
	}{
		{
			name:     "Empty board safe position",
			size:     4,
			queens:   []board.Position{},
			testPos:  board.Position{Row: 0, Col: 0},
			expected: true,
		},
		{
			name:     "Out of bounds row negative",
			size:     4,
			queens:   []board.Position{},
			testPos:  board.Position{Row: -1, Col: 0},
			expected: false,
		},
		{
			name:     "Out of bounds col too large",
			size:     4,
			queens:   []board.Position{},
			testPos:  board.Position{Row: 0, Col: 4},
			expected: false,
		},
		{
			name:     "Same row conflict",
			size:     4,
			queens:   []board.Position{{Row: 0, Col: 1}},
			testPos:  board.Position{Row: 0, Col: 3},
			expected: false,
		},
		{
			name:     "Same column conflict",
			size:     4,
			queens:   []board.Position{{Row: 1, Col: 2}},
			testPos:  board.Position{Row: 3, Col: 2},
			expected: false,
		},
		{
			name:     "Diagonal conflict primary",
			size:     4,
			queens:   []board.Position{{Row: 1, Col: 1}},
			testPos:  board.Position{Row: 2, Col: 2},
			expected: false,
		},
		{
			name:     "Diagonal conflict secondary",
			size:     4,
			queens:   []board.Position{{Row: 1, Col: 2}},
			testPos:  board.Position{Row: 2, Col: 1},
			expected: false,
		},
		{
			name:     "Completely safe placement",
			size:     4,
			queens:   []board.Position{{Row: 0, Col: 1}},
			testPos:  board.Position{Row: 1, Col: 3},
			expected: true,
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			b := board.NewBoard(tt.size)
			b.Queens = tt.queens
			res := b.IsSafe(tt.testPos)
			if res != tt.expected {
				t.Errorf("IsSafe() = %v, expected %v", res, tt.expected)
			}
		})
	}
}

func TestAddAndRemoveQueen(t *testing.T) {
	b := board.NewBoard(4)
	pos1 := board.Position{Row: 0, Col: 1}

	if !b.AddQueen(pos1) {
		t.Errorf("Failed to add queen to empty board")
	}

	// Try adding invalid queen
	posInvalid := board.Position{Row: 0, Col: 2}
	if b.AddQueen(posInvalid) {
		t.Errorf("Expected adding queen in same row to fail")
	}

	// Remove queen
	b.RemoveQueen(pos1)
	if len(b.Queens) != 0 {
		t.Errorf("Expected 0 queens after removal, got %d", len(b.Queens))
	}
}

func TestGetAttackHeatmap(t *testing.T) {
	b := board.NewBoard(3)
	b.AddQueen(board.Position{Row: 1, Col: 1}) // Queen in center

	heatmap := b.GetAttackHeatmap()
	// The center should have attacks from the queen itself
	if heatmap[1][1] == 0 {
		t.Errorf("Expected heatmap to record queen's self/presence, got %d", heatmap[1][1])
	}

	// Corners are diagonally attacked
	if heatmap[0][0] == 0 || heatmap[2][2] == 0 {
		t.Errorf("Expected diagonals to be attacked")
	}
}

func TestBoardString(t *testing.T) {
	b := board.NewBoard(2)
	b.AddQueen(board.Position{Row: 0, Col: 0})
	str := b.String()
	if str == "" {
		t.Errorf("Expected non-empty string representation")
	}
}

package solver_test

import (
	"testing"
	"nqueen-zoo/pkg/solver"
)

func TestBacktrackingSolver_Solve(t *testing.T) {
	s := &solver.BacktrackingSolver{}

	tests := []struct {
		n          int
		shouldPass bool
	}{
		{n: 1, shouldPass: true},
		{n: 2, shouldPass: false},
		{n: 3, shouldPass: false},
		{n: 4, shouldPass: true},
		{n: 8, shouldPass: true},
	}

	for _, tt := range tests {
		t.Run(string(rune(tt.n)), func(t *testing.T) {
			b, err := s.Solve(tt.n)
			if tt.shouldPass {
				if err != nil {
					t.Fatalf("Expected solution for N=%d, but got error: %v", tt.n, err)
				}
				if len(b.Queens) != tt.n {
					t.Fatalf("Expected %d queens, got %d", tt.n, len(b.Queens))
				}
