package solver

import (
	"fmt"
	"math/rand"
	"time"

	"nqueen-zoo/pkg/board"
)

// Step represents a single step in the solving process, including narrative for educational purposes.
type Step struct {
	Board       *board.Board
	Narrative   string
	IsBacktrack bool
}

// Solver defines the interface for different N-Queens algorithms.
type Solver interface {
	Solve(n int) (*board.Board, error)
	GetSteps(n int) <-chan Step
}

// BacktrackingSolver implements a backtracking algorithm with educational narrative.
type BacktrackingSolver struct{}

// Solve finds a single solution using the standard recursive approach.
func (s *BacktrackingSolver) Solve(n int) (*board.Board, error) {
	b := board.NewBoard(n)
	if s.backtrack_recursive(b, 0, n) {
		return b, nil
	}
	return nil, fmt.Errorf("no solution found")
}

func (s *BacktrackingSolver) backtrack_recursive(b *board.Board, row int, n int) bool {
	if row == n {
		return true
	}

	for col := 0; col < n; col++ {
		pos := board.Position{Row: row, Col: col}
		if b.IsSafe(pos) {
			b.AddQueen(pos)
			if s.backtrack_recursive(b, row+1, n) {
				return true
			}
			b.RemoveQueen(pos)
		}
	}
	return false
}

// GetSteps generates a channel of steps for educational playback.
func (s *BacktrackingSolver) GetSteps(n int) <-chan Step {
	ch := make(chan Step)
	go func() {
		defer close(ch)
		b := board.NewBoard(n)

		var backtrack func(int) bool
		backtrack = func(row int) bool {
			if row == n {
				ch <- Step{
					Board:     b,
					Narrative: "🎉 Queen placement complete! We've found a valid configuration.",
					IsBacktrack: false,
				}
				return true
			}

			for col := 0; col < n; col++ {
				pos := board.Position{Row: row, Col: col}
				if b.IsSafe(pos) {
					b.AddQueen(pos)
					narrative := fmt.Sprintf("Trying to place a queen at Row %d, Column %d...", row, col)
					ch <- Step{Board: b, Narrative: narrative, IsBacktrack: false}

					if backtrack(row + 1) {
						return true
					}

					b.RemoveQueen(pos)
					ch <- Step{
						Board:       b,
						Narrative:   fmt.Sprintf("Row %d led to a dead end eventually! Backtracking from Row %d...", row+1, row),
						IsBacktrack: true,
					}
				}
			}
			return false
		}

		backtrack(0)
	}()
	return ch
}

// MinConflictsSolver implements the Min-Conflicts local search heuristic for large N.
type MinConflictsSolver struct{}

// Solve finds a single solution using min-conflicts.
func (s *MinConflictsSolver) Solve(n int) (*board.Board, error) {
	if n < 4 {
		if n == 1 {
			b := board.NewBoard(1)
			b.AddQueen(board.Position{Row: 0, Col: 0})
			return b, nil
		}
		return nil, fmt.Errorf("no solution for N=%d", n)
	}

	rand.Seed(time.Now().UnixNano())

	// Try multiple random restarts if we get stuck in local minima
	for restart := 0; restart < 20; restart++ {
		queens := make([]int, n)
		rows := make([]int, n)
		diag1 := make([]int, 2*n)
		diag2 := make([]int, 2*n)

		// Greedy initial assignment: place each queen in a column that minimizes immediate conflicts
		for r := 0; r < n; r++ {
			bestCol := 0
			minC := 999999
			for c := 0; c < n; c++ {
				cCount := rows[c] + diag1[r-c+n] + diag2[r+c]
				if cCount < minC {
					minC = cCount
					bestCol = c
				}
			}
			queens[r] = bestCol
			rows[bestCol]++
			diag1[r-bestCol+n]++
			diag2[r+bestCol]++
		}

		maxSteps := n * 200
		for step := 0; step < maxSteps; step++ {
			// Find all queens with conflicts
			conflictedRows := []int{}
			for r := 0; r < n; r++ {
				c := queens[r]
				if (rows[c] + diag1[r-c+n] + diag2[r+c] - 3) > 0 {
					conflictedRows = append(conflictedRows, r)
				}
			}

			if len(conflictedRows) == 0 {
				b := board.NewBoard(n)
				for r := 0; r < n; r++ {
					b.ForceAddQueen(board.Position{Row: r, Col: queens[r]})
				}
				return b, nil
			}

			// Pick a random conflicted queen
			chosenRow := conflictedRows[rand.Intn(len(conflictedRows))]
			currentCol := queens[chosenRow]

			// Remove current queen's influence to evaluate potential moves
			rows[currentCol]--
			diag1[chosenRow-currentCol+n]--
			diag2[chosenRow+currentCol]--

			// Find columns with minimal conflicts
			minC := 999999
			bestCols := []int{}
			for c := 0; c < n; c++ {
				cCount := rows[c] + diag1[chosenRow-c+n] + diag2[chosenRow+c]
				if cCount < minC {
					minC = cCount
					bestCols = []int{c}
				} else if cCount == minC {
					bestCols = append(bestCols, c)
				}
			}

			// Choose one at random among best
			newCol := bestCols[rand.Intn(len(bestCols))]
			queens[chosenRow] = newCol

			rows[newCol]++
			diag1[chosenRow-newCol+n]++
			diag2[chosenRow+newCol]++
		}
	}

	return nil, fmt.Errorf("min-conflicts failed to find solution")
}

func (s *MinConflictsSolver) GetSteps(n int) <-chan Step {
	ch := make(chan Step)
	go func() {
		defer close(ch)
		b, err := s.Solve(n)
		if err == nil {
			ch <- Step{Board: b, Narrative: "Min-Conflicts converged to a valid solution!", IsBacktrack: false}
		} else {
			ch <- Step{Board: board.NewBoard(n), Narrative: "Failed to solve using Min-Conflicts.", IsBacktrack: true}
		}
	}()
	return ch
}

